/**
 * @dsh-external/dsh-wechat-chat — client half.
 * 微信风格气泡聊天(小鲸鱼 / kamix)。
 *
 * 架构:头像/昵称/时间戳全部走 CSS 伪元素 + CSS 变量 —— 观察器只负责
 * 把每行的昵称与时间写入该行的 --wcx-name / --wcx-time 内联变量,
 * 不再注入任何 DOM 节点,因此 React 重渲染无法破坏增强(之前的 img/wrap
 * 注入会被 React 按索引比对清掉)。
 *
 * 模块格式:window.__ModuleLoader__.load({ id, factory })。
 */
window.__ModuleLoader__.load({
  id: '@dsh-external/dsh-wechat-chat',
  factory: (require) => {
    var module = { exports: {} }
    var exports = module.exports

    var USER_NAME = 'kamix'
    var ASSISTANT_NAME = '小鲸鱼'
    var USER_AVATAR = 'https://i1.hdslb.com/bfs/face/e213710f658fdeca5e8f0665b456eccdea2d9b26.jpg@150w_150h.jpg'
    var ASSISTANT_AVATAR = 'data:image/png;base64,'

    var CSS = `
/* ============ WeChat-style bubble chat (小鲸鱼 / kamix) ============ */

/* 1) Chat backdrop: WeChat light gray (only when a conversation is live) */
[data-phase="active"] [data-conversation-scroll],
[data-phase="settling"] [data-conversation-scroll] {
  background: #EDEDED;
}

/* 2) Row layout: user right, assistant left; avatar = ::before, name/time = ::after */
[data-chat-flow-kind="user"],
[data-chat-flow-kind="assistant-step"] {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 8px;
}
[data-chat-flow-kind="user"] {
  flex-direction: row-reverse;
}
[data-chat-flow-kind="user"] > *,
[data-chat-flow-kind="assistant-step"] > * {
  flex: 1 1 0%;
  min-width: 0;
}

/* 3) Avatars via ::before (React cannot remove pseudo-elements) */
[data-chat-flow-kind="user"]::before,
[data-chat-flow-kind="assistant-step"]::before {
  content: "";
  flex: none;
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  background-color: #ffffff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12);
}
[data-chat-flow-kind="user"]::before {
  /* layered backgrounds: bilibili photo over an orange fallback tile */
  background-image: url('${USER_AVATAR}'),
    linear-gradient(135deg, #ffb75e, #ed8f03);
}
[data-chat-flow-kind="assistant-step"]::before {
  background-image: url('${ASSISTANT_AVATAR}');
}

/* 4) Name + timestamp via ::after (absolute above the bubble, no layout shift) */
[data-chat-flow-kind="user"]::after,
[data-chat-flow-kind="assistant-step"]::after {
  content: var(--wcx-name, '') var(--wcx-time, '');
  position: absolute;
  top: -20px;
  font-size: 12px;
  line-height: 16px;
  color: var(--dsw-alias-label-tertiary);
  white-space: nowrap;
  pointer-events: none;
  user-select: none;
}
[data-chat-flow-kind="user"]::after {
  content: var(--wcx-time, '') var(--wcx-name, '');
  right: 48px;
}
[data-chat-flow-kind="assistant-step"]::after {
  content: var(--wcx-name, '') var(--wcx-time, '');
  left: 48px;
}
[data-chat-flow-kind="user"] > :first-child,
[data-chat-flow-kind="assistant-step"] > :first-child {
  margin-top: 20px;
}

/* 5) User bubble: WeChat green, tail on the right */
[data-chat-flow-kind="user"] .gdEzaW_bubble,
[data-chat-flow-kind="user"] [class*="bubble"] {
  position: relative;
  background: #95ec69;
  color: #101010;
  border-radius: 14px;
  padding: 12px 16px;
  font-size: 15px;
  line-height: 22px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}
[data-chat-flow-kind="user"] .gdEzaW_bubble::after,
[data-chat-flow-kind="user"] [class*="bubble"]::after {
  content: "";
  position: absolute;
  top: 14px;
  right: -5px;
  width: 10px;
  height: 10px;
  background: #95ec69;
  transform: rotate(45deg);
  border-radius: 2px;
}
[data-chat-flow-kind="user"] .gdEzaW_userStack {
  min-width: 0;
  max-width: min(340px, 88%);
}

/* 6) Assistant bubble: white, tail on the left */
[data-chat-flow-kind="assistant-step"] .Sxvs8a_root {
  position: relative;
  box-sizing: border-box;
  background: #ffffff;
  color: #1a1a1a;
  border-radius: 14px;
  padding: 12px 16px;
  max-width: min(660px, 88%);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}
[data-chat-flow-kind="assistant-step"] .Sxvs8a_root::after {
  content: "";
  position: absolute;
  top: 14px;
  left: -5px;
  width: 10px;
  height: 10px;
  background: #ffffff;
  transform: rotate(45deg);
  border-radius: 2px;
}

/* 7) Dark mode: keyed to the app's own marker (body[data-ds-dark-theme]) */
body[data-ds-dark-theme] [data-phase="active"] [data-conversation-scroll],
body[data-ds-dark-theme] [data-phase="settling"] [data-conversation-scroll] {
  background: #111111;
}
body[data-ds-dark-theme] [data-chat-flow-kind="user"] .gdEzaW_bubble,
body[data-ds-dark-theme] [data-chat-flow-kind="user"] [class*="bubble"] {
  background: #95ec69;
  color: #101010;
}
body[data-ds-dark-theme] [data-chat-flow-kind="user"] .gdEzaW_bubble::after,
body[data-ds-dark-theme] [data-chat-flow-kind="user"] [class*="bubble"]::after {
  background: #95ec69;
}
body[data-ds-dark-theme] [data-chat-flow-kind="assistant-step"] .Sxvs8a_root {
  background: #262626;
  color: #e6e6e6;
}
body[data-ds-dark-theme] [data-chat-flow-kind="assistant-step"] .Sxvs8a_root::after {
  background: #262626;
}
body[data-ds-dark-theme] [data-chat-flow-kind="user"]::before,
body[data-ds-dark-theme] [data-chat-flow-kind="assistant-step"]::before {
  background-color: #262626;
}

/* 8) "Deep diving..." -> "小鲸鱼正在thinking中" (TurnStatus text override) */
.Md3f7G_turnStatus {
  font-size: 0;
}
.Md3f7G_turnStatus::before {
  content: "小鲸鱼正在thinking中";
  font: var(--dsw-font-s-strong-14);
  color: var(--dsw-static-deepseek-500);
}
.Md3f7G_turnStatusClock {
  font-size: 13px;
}
`

    /* ---------- per-row CSS variables (names + timestamps) ---------- */

    function formatNow() {
      var d = new Date()
      function pad(n) { return n < 10 ? '0' + n : String(n) }
      return pad(d.getHours()) + ':' + pad(d.getMinutes())
    }

    function styleRow(row) {
      var kind = row.getAttribute('data-chat-flow-kind')
      if (kind !== 'user' && kind !== 'assistant-step') return
      var name = kind === 'user' ? USER_NAME : ASSISTANT_NAME
      var time = ''
      var next = row.nextElementSibling
      if (next && next.hasAttribute('data-turn-tail')) {
        var t = next.querySelector('.p-xYUq_timeStart, .p-xYUq_timeEnd')
        if (t) time = t.textContent.trim()
      }
      if (!time) time = formatNow()
      row.style.setProperty('--wcx-name', JSON.stringify(name))
      // user: "11:48 kamix"; assistant: "小鲸鱼 14:32"
      row.style.setProperty('--wcx-time', kind === 'user' ? JSON.stringify(time + ' ') : JSON.stringify(' ' + time))
    }

    function styleAll() {
      var rows = document.querySelectorAll('[data-chat-flow-kind]')
      for (var i = 0; i < rows.length; i++) styleRow(rows[i])
    }

    /* ---------- DOM audit (development only) ---------- */

    function collectAudit() {
      var out = {
        ts: Date.now(),
        readyState: document.readyState,
        styleInjected: !!document.querySelector('style[data-wechat-chat]'),
        kinds: {},
        rows: {},
      }
      var rows = document.querySelectorAll('[data-chat-flow-kind]')
      for (var i = 0; i < rows.length; i++) {
        var k = rows[i].getAttribute('data-chat-flow-kind')
        out.kinds[k] = (out.kinds[k] || 0) + 1
      }
      for (const kind of ['user', 'assistant-step']) {
        const row = document.querySelector('[data-chat-flow-kind="' + kind + '"]')
        if (!row) continue
        const content = row.firstElementChild
        const bubble = row.querySelector('.gdEzaW_bubble, .Sxvs8a_root, [class*="bubble"]')
        const before = getComputedStyle(row, '::before')
        const after = getComputedStyle(row, '::after')
        out.rows[kind] = {
          children: row.children.length,
          nextKind: row.nextElementSibling ? row.nextElementSibling.getAttribute('data-chat-flow-kind') : null,
          rowWidth: Math.round(row.getBoundingClientRect().width),
          contentWidth: content ? Math.round(content.getBoundingClientRect().width) : null,
          bubbleWidth: bubble ? Math.round(bubble.getBoundingClientRect().width) : null,
          avatarBg: before.backgroundImage.slice(0, 40),
          nameContent: after.content,
          topMargin: content ? getComputedStyle(content).marginTop : null,
        }
      }
      const status = document.querySelector('.Md3f7G_turnStatus')
      out.turnStatusText = status ? status.textContent : null
      return out
    }

    function report() {
      try {
        var payload = JSON.stringify(collectAudit())
        fetch('/@dsh-external/dsh-wechat-chat/api/audit?data=' + encodeURIComponent(payload), {
          method: 'GET',
        }).catch(function () {})
      } catch (e) {}
    }

    var scheduled = null
    function schedule() {
      if (scheduled) return
      scheduled = setTimeout(function () {
        scheduled = null
        styleAll()
      }, 120)
    }

    /* ---------- plugin apply ---------- */

    function apply(ctx) {
      if (typeof document === 'undefined') return

      // 1) stylesheet
      var tag = document.querySelector('style[data-wechat-chat]')
      if (!tag) {
        tag = document.createElement('style')
        tag.setAttribute('data-wechat-chat', '')
        tag.textContent = CSS
        document.head.appendChild(tag)
      }
      ctx.effect(function () {
        return function () {
          if (tag && tag.parentNode) tag.parentNode.removeChild(tag)
        }
      })

      // 2) per-row CSS variables (names/timestamps)
      var mo = new MutationObserver(function () { schedule() })
      mo.observe(document.documentElement, { childList: true, subtree: true })
      ctx.effect(function () {
        return function () {
          mo.disconnect()
          if (scheduled) clearTimeout(scheduled)
        }
      })
      styleAll()

      // 3) audit rounds (immediate + 1.2s/3.5s/8s + every 4s for a while)
      var timers = [0, 1200, 3500, 8000].map(function (d) { return setTimeout(report, d) })
      var iv = setInterval(report, 4000)
      ctx.effect(function () {
        return function () {
          for (var i = 0; i < timers.length; i++) clearTimeout(timers[i])
          clearInterval(iv)
        }
      })

      try { console.log('[dsh-wechat-chat] client activated') } catch (e) {}
    }

    var inject = ['slots']

    exports.apply = apply
    exports.inject = inject
    return module.exports
  },
})
